def copy_to_creators(apps, schema_editor):
    # The old single field was only ever shown to the place's creator (plus
    # admins), so it becomes the creator's own note. Notes whose creator
    # account no longer exists have no owner left to give them to.
    Location = apps.get_model("tracker", "Location")
    PrivateNote = apps.get_model("tracker", "PrivateNote")
    for loc in Location.objects.exclude(private_notes="").exclude(created_by=None):
        if loc.private_notes.strip():
            PrivateNote.objects.create(location=loc, user_id=loc.created_by_id, text=loc.private_notes.strip())


def copy_back_to_locations(apps, schema_editor):
    Location = apps.get_model("tracker", "Location")
    PrivateNote = apps.get_model("tracker", "PrivateNote")
    for note in PrivateNote.objects.select_related("location"):
        if note.location.created_by_id == note.user_id:
            Location.objects.filter(pk=note.location_id).update(private_notes=note.text)


